use coap_lite::{Client, Message, Method, Code};
use std::net::SocketAddr;
use std::time::Duration;
use std::sync::Arc;
use std::sync::Mutex;
use std::collections::HashMap;

pub struct CoapClient {
    client: Client,
    target_addr: SocketAddr,
    request_timeout: Duration,
    request_retries: u32,
}

impl CoapClient {
    pub fn new(config: CoapConfig) -> Self {
        CoapClient {
            client: Client::new(),
            target_addr: config.target_addr,
            request_timeout: config.request_timeout,
            request_retries: config.request_retries,
        }
    }

    pub fn acquire_data(&self) -> Vec<Value> {
        let mut data = Vec::new();

        for _ in 0..self.request_retries {
            match self.client.request(Method::Get, self.target_addr, None, self.request_timeout) {
                Ok(mut response) => {
                    if response.code() == Code::Content {
                        let payload = response.payload().unwrap_or_default();
                        let data: Vec<Value> = serde_json::from_slice(&payload).unwrap_or_default();
                        data.into_iter().for_each(|d| data.push(d));
                        return data;
                    }
                },
                Err(e) => {
                    eprintln!("CoAP request failed: {}", e);
                }
            }
        }

        data
    }
}
