import random
from typing import List, Optional, Dict, Any

class Card:
    """Represents a single playing card with a suit and rank."""
    SUITS = ['hearts', 'diamonds', 'clubs', 'spades']
    RANKS = ['Ace', '2', '3', '4', '5', '6', '7', '8', '9', '10', 'Jack', 'Queen', 'King']

    def __init__(self, suit: str, rank: str):
        self.suit = suit
        self.rank = rank

    def __str__(self):
        return f"{self.rank} of {self.suit}"

    def __repr__(self):
        return f"Card(suit='{self.suit}', rank='{self.rank}')"

    def get_value(self) -> int:
        """Returns the numerical value of the card for comparison."""
        if self.rank == 'Ace':
            return 1
        elif self.rank in ['Jack', 'Queen', 'King']:
            return 10
        else:
            return int(self.rank)

class Deck:
    """Represents a standard deck of 52 playing cards."""
    def __init__(self):
        self.cards = [Card(suit, rank) for suit in Card.SUITS for rank in Card.RANKS]
        self.shuffle()

    def shuffle(self):
        """Shuffles the deck of cards."""
        random.shuffle(self.cards)

    def deal(self, num_cards: int) -> List[Card]:
        """Deals a specified number of cards from the deck."""
        if num_cards > len(self.cards):
            raise ValueError("Cannot deal more cards than are in the deck.")
        dealt_cards = self.cards[:num_cards]
        self.cards = self.cards[num_cards:]
        return dealt_cards

    def draw(self) -> Optional[Card]:
        """Draws a single card from the deck."""
        if not self.cards:
            return None
        return self.cards.pop(0)

class DiscardPile:
    """Manages the discard pile where players can discard cards."""
    def __init__(self):
        self.cards = []

    def add_card(self, card: Card):
        """Adds a card to the discard pile."""
        self.cards.append(card)
